 fn spawn(&mut self,command:&str,cwd:Option<PathBuf>,timeout:u64)->Result<Value,String>{let job_cwd=cwd.unwrap_or_else(||self.cwd.clone().into()).canonicalize().map_err(|e|format!("cannot resolve background workdir: {e}"))?;let script=format!("eval {}\n",quote(command));let mut cmd=Command::new("/bin/bash");cmd.args(["--noprofile","--norc","-c",&script]).current_dir(&job_cwd).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).process_group(0);apply_env(&mut cmd,&self.exports);let mut child=cmd.spawn().map_err(|e|e.to_string())?;let output=Arc::new(Mutex::new(Output::default()));drain(child.stdout.take().unwrap(),output.clone());drain(child.stderr.take().unwrap(),output.clone());let pid=child.id()as i32;let proc=Arc::new(Mutex::new(Proc{child,pid,code:None,reaped:false}));let timer=Arc::clone(&proc);thread::spawn(move||{thread::sleep(Duration::from_secs(timeout));timer.lock().unwrap().kill();});self.next+=1;let id=format!("job-{}",self.next);let input=proc.lock().unwrap().child.stdin.take();self.jobs.insert(id.clone(),Job{proc,input,output,command:command.into()});Ok(json!({"session_id":id,"pid":pid,"status":"running","cwd":job_cwd}))}
